/**
 * registry.ts — Single source of truth for every analysis / feature
 * / catalog module shipped in NexyFab.
 *
 * After 30+ depth-batches of modules, the UI couldn't reasonably
 * import each one individually — a command palette, ribbon, search
 * panel, and route-specific menu all need to enumerate "what's
 * available right now". This registry is that enumeration.
 *
 * Each entry declares:
 *   - **id**: stable, scoped (e.g. "fea.buckling").
 *   - **category**: domain bucket for the ribbon.
 *   - **tags**: free-form search tokens.
 *   - **routes**: which route(s) this module shows up under
 *     (modeling / drawing / render / assembly / inspection / cam / etc).
 *   - **license**: free / pro / pro-plus — drives the freemium gate.
 *   - **entryHint**: where to find the actual implementation
 *     (relative path under shape-generator/).
 *
 * The registry intentionally does NOT import the implementation files
 * — keeping it import-free means it doesn't bloat the initial bundle.
 * Panels that need an implementation call `loadModule(id)` which
 * dynamically imports the file.
 */

export type FeatureCategory =
  | 'modeling' | 'sketch' | 'surface' | 'mesh' | 'topology'
  | 'assembly' | 'pdm'
  | 'drawing' | 'pmi' | 'inspection'
  | 'simulation' | 'cfd' | 'composite' | 'dynamic'
  | 'cam' | 'edm' | 'plant'
  | 'sheet-metal' | 'mold' | 'plastic'
  | 'routing' | 'wire' | 'hvac'
  | 'rendering' | 'animation' | 'xr'
  | 'standard-parts' | 'materials' | 'tooling'
  | 'estimation' | 'cost' | 'supplier' | 'dfm'
  | 'automation' | 'scripting' | 'ai'
  | 'interop' | 'export' | 'import'
  | 'quality' | 'tolerance';

export type FeatureRoute =
  | 'modeling' | 'sketch' | 'assembly' | 'drawing' | 'render'
  | 'inspection' | 'cam' | 'mold' | 'sheet-metal' | 'plant'
  | 'wiring' | 'hvac' | 'cost' | 'dfm' | 'hub';

export type FeatureLicense = 'free' | 'pro' | 'pro-plus' | 'enterprise';

export interface FeatureRegistryEntry {
  id: string;
  /** Human-readable name shown in the command palette / ribbon. */
  name: string;
  category: FeatureCategory;
  /** Routes where this module appears in the UI. */
  routes: FeatureRoute[];
  /** Free-form search tokens. */
  tags: string[];
  license: FeatureLicense;
  /** Filesystem location for dynamic import. */
  entryHint: string;
  /** Short description for tooltip / palette description. */
  description: string;
}

