// ── Search / filter ─────────────────────────────────────────────

export function findByCategory(category: FeatureCategory): FeatureRegistryEntry[] {
  return FEATURE_REGISTRY.filter(e => e.category === category);
}

export function findByRoute(route: FeatureRoute): FeatureRegistryEntry[] {
  return FEATURE_REGISTRY.filter(e => e.routes.includes(route));
}

export function findById(id: string): FeatureRegistryEntry | null {
  return FEATURE_REGISTRY.find(e => e.id === id) ?? null;
}

/** Substring search across name + tags + description (case-insensitive). */
export function searchFeatures(query: string): FeatureRegistryEntry[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return FEATURE_REGISTRY.filter(e =>
    e.name.toLowerCase().includes(q)
    || e.description.toLowerCase().includes(q)
    || e.tags.some(t => t.includes(q))
    || e.id.includes(q),
  );
}

/** Filter to entries the current freemium tier can access. */
export function filterByLicense(
  entries: FeatureRegistryEntry[],
  userTier: FeatureLicense,
): FeatureRegistryEntry[] {
  const tierOrder: FeatureLicense[] = ['free', 'pro', 'pro-plus', 'enterprise'];
  const userIndex = tierOrder.indexOf(userTier);
  return entries.filter(e => tierOrder.indexOf(e.license) <= userIndex);
}

/** Summary statistics for the registry. */
export interface RegistryStats {
  totalEntries: number;
  byCategory: Record<string, number>;
  byLicense: Record<string, number>;
  byRoute: Record<string, number>;
}

export function getRegistryStats(): RegistryStats {
  const byCategory: Record<string, number> = {};
  const byLicense: Record<string, number> = {};
  const byRoute: Record<string, number> = {};
  for (const e of FEATURE_REGISTRY) {
    byCategory[e.category] = (byCategory[e.category] ?? 0) + 1;
    byLicense[e.license] = (byLicense[e.license] ?? 0) + 1;
    for (const r of e.routes) {
      byRoute[r] = (byRoute[r] ?? 0) + 1;
    }
  }
  return { totalEntries: FEATURE_REGISTRY.length, byCategory, byLicense, byRoute };
}
